using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentySixSpecs
{
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    internal static GameState Fixture()
    {
        var s=StageTwentyFiveSpecs.Fixture();var c=s.Cities[0];c.Buildings.UnionWith(["workshop","factory",Manufacturing.Toolmakers]);c.ProductionPaused=false;c.Food=0;c.Project="treasury";c.RepeatProject=true;c.MarketStocks[TradeGood.Iron]=40;c.MarketStocks[TradeGood.Dyes]=20;return s;
    }
    private static void Step(GameState s){s.PendingEvent=null;Assert(Engine.EndTurn(s).Success,"Turn failed");}
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    private static void Balanced(GameState s)
    {foreach(var c in s.Cities)foreach(var l in c.LastMarketLines)Assert(Math.Abs(l.Opening+l.Produced+l.DomesticIn+l.ForeignIn-l.DomesticOut-l.ForeignOut-l.Consumed-l.IndustrialUsed-l.Lost-l.Closing)<.00001&&Math.Abs(l.Closing-c.MarketStocks[l.Good])<.00001,"Unbalanced commodity ledger");}
    private static void Connect(GameState s,int from,int to)
    {for(int x=from;x<=to;x++){var t=s.Tiles[12*s.Width+x];t.Road=true;t.RoadOwner=t.Owner=x<=16?0:1;}s.InvalidateLogistics();}
    private static void Trade(GameState s)
    {s.Cities[0].Buildings.Add("market");s.Cities[1].Buildings.Add("market");s.Factions[1].Technologies.Add("trade");s.Relation(0,1).Trade=true;Connect(s,12,20);}
    public static void Run(Action<string,Action> test)
    {
        test("Processing projects have legal technologies and cannot be built in legacy campaigns",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Remove(Manufacturing.Toolmakers);Assert(Engine.SetProject(s,c.Id,Manufacturing.Toolmakers).Success,"Legal toolmakers rejected");s.Player.Technologies.Remove("engineering");Assert(ProductionPlanning.ProjectError(s,c,Manufacturing.Toolmakers)!=null,"Technology skipped");s.EpochCampaign=false;Assert(Manufacturing.ProjectError(s,Manufacturing.Weavers)!=null,"Legacy processing allowed");});
        test("A real city project builds a workshop with no invented goods or active policy",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Remove(Manufacturing.Toolmakers);double cost=Engine.Economy(s,0).AdministrationCost;Engine.SetProject(s,c.Id,Manufacturing.Toolmakers);c.Production=159.9;Step(s);Assert(c.Buildings.Contains(Manufacturing.Toolmakers)&&c.MarketStocks[TradeGood.Tools]==0&&c.IndustryShare==0&&Engine.Economy(s,0).AdministrationCost>=cost+1.5,"Construction output or upkeep wrong");Valid(s);});
        test("The crafting policy commits no immediate materials work or goods",()=>{var s=Fixture();var c=s.Cities[0];double iron=c.MarketStocks[TradeGood.Iron],work=c.Production;Assert(Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50).Success&&c.MarketStocks[TradeGood.Iron]==iron&&c.MarketStocks[TradeGood.Tools]==0&&c.Production==work,"Instant manufactured goods");});
        test("Policy changes validate owner recipe and cooldown without partial mutation",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,25);string before=SaveGame.Serialize(s);Assert(!Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50).Success&&!Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,0,1).Success&&!Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Textiles,50).Success&&SaveGame.Serialize(s)==before,"Invalid policy changed state");});
        test("Manufacturing forecasts preserve exact stocks campaign and RNG",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);string before=SaveGame.Serialize(s);var a=Manufacturing.Quote(s,c,100);var b=Manufacturing.Quote(s,c,100);Assert(a.Batches>0&&a.Batches==b.Batches&&a.Work==b.Work&&SaveGame.Serialize(s)==before,"Forecast mutated state");});
        test("Tools spend real iron and work and keep every commodity ledger balanced",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);var control=SaveGame.Deserialize(SaveGame.Serialize(s));control.Cities[0].IndustryShare=0;Step(s);Step(control);Assert(c.LastIndustryBatches>0&&c.MarketStocks[TradeGood.Tools]==c.LastIndustryBatches&&c.LastIndustryWork==c.LastIndustryBatches*6&&c.LastMarketLines.Single(l=>l.Good==TradeGood.Iron).IndustrialUsed==c.LastIndustryBatches*2&&Math.Abs(c.Production+c.LastIndustryWork-control.Cities[0].Production)<.00001,"Tools created free work or iron");Balanced(s);Valid(s);});
        test("Weaving converts each dye unit into two textiles at the quoted work cost",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(Manufacturing.Weavers);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Textiles,50);Step(s);Assert(c.LastIndustryBatches>0&&c.MarketStocks[TradeGood.Textiles]==c.LastIndustryBatches*2&&c.LastIndustryWork==c.LastIndustryBatches*4&&c.LastMarketLines.Single(l=>l.Good==TradeGood.Dyes).IndustrialUsed==c.LastIndustryBatches,"Weaving recipe was not conserved");Balanced(s);Valid(s);});
        test("A partial work budget never creates a fractional batch",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);var quote=Manufacturing.Quote(s,c,11.9);Assert(quote.Batches==0&&quote.Work==0&&quote.Inputs.Count==0,"Partial labor created a batch");});
        test("Missing ingredients leave the entire processing budget to ordinary construction",()=>{var s=Fixture();var c=s.Cities[0];c.MarketStocks[TradeGood.Iron]=0;Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));copy.Cities[0].IndustryShare=0;Step(s);Step(copy);Assert(c.LastIndustryBatches==0&&c.LastIndustryWork==0&&Math.Abs(c.Production-copy.Cities[0].Production)<.00001,"Missing materials consumed labor");Balanced(s);});
        test("Full product storage blocks work and prevents manufacturing overflow",()=>{var s=Fixture();var c=s.Cities[0];c.MarketStocks[TradeGood.Tools]=Markets.Capacity(c);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));copy.Cities[0].IndustryShare=0;Step(s);Step(copy);Assert(c.LastIndustryBatches==0&&c.MarketStocks[TradeGood.Tools]==Markets.Capacity(c)&&c.Production==copy.Cities[0].Production,"Full storage wasted labor or inputs");Balanced(s);});
        test("A two-item textile batch requires room for both items",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(Manufacturing.Weavers);c.MarketStocks[TradeGood.Textiles]=Markets.Capacity(c)-1;Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Textiles,50);Step(s);Assert(c.LastIndustryBatches==0&&c.MarketStocks[TradeGood.Textiles]==Markets.Capacity(c)-1,"Incomplete storage created or lost products");Balanced(s);});
        test("Repeated market previews and market ticks never manufacture early products",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Markets.Plan(s);Markets.Plan(s);Markets.Tick(s);Markets.Tick(s);Assert(c.MarketStocks[TradeGood.Tools]==0&&c.LastIndustryTurn==0,"Market phase performed city processing");Step(s);Assert(c.LastIndustryBatches>0&&c.MarketStocks[TradeGood.Tools]==c.LastIndustryBatches,"Processing executed more than once");Balanced(s);Valid(s);});
        test("Districts and military supply receive work before manufacturing without double spending",()=>{var s=Fixture();var c=s.Cities[0];c.Population=12;s.Player.Stability=100;c.Loyalty=c.Prosperity=100;c.Buildings.UnionWith([Manufacturing.Weavers,FieldLogistics.Depot]);Assert(Districts.Begin(s,c.Id,c.Tile+1,DistrictKind.Gardens,DistrictFunding.Public).Success&&Districts.SetShare(s,c.Id,50).Success,"District setup failed");FieldLogistics.SetAllocation(s,c.Id,50);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Textiles,50);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));copy.Cities[0].IndustryShare=0;Step(s);Step(copy);Assert(c.LastIndustryBatches>0&&s.Districts.Single().Work==copy.Districts.Single().Work&&c.MilitarySupplies==copy.Cities[0].MilitarySupplies&&Math.Abs(c.Production+c.LastIndustryWork-copy.Cities[0].Production)<.00001,"Competing budgets double-spent city work");Balanced(s);Valid(s);});
        test("Connected own warehouses supply ingredients with explicit source receipts",()=>{var s=Fixture();var c=s.Cities[0];c.MarketStocks[TradeGood.Iron]=0;var donor=Engine.AddCity(s,0,12*s.Width+16,"Hutnicze Wzgórze");donor.ProductionPaused=true;donor.MarketStocks[TradeGood.Iron]=40;Connect(s,12,16);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);Assert(c.LastIndustryBatches>0&&c.LastIndustryInputs.All(i=>i.CityId==donor.Id)&&donor.LastMarketLines.Single(l=>l.Good==TradeGood.Iron).IndustrialUsed==c.LastIndustryBatches*2,"Regional inputs teleported or lost their receipt");Balanced(s);Valid(s);});
        test("A broken road prevents production from a disconnected warehouse",()=>{var s=Fixture();var c=s.Cities[0];c.MarketStocks[TradeGood.Iron]=0;var donor=Engine.AddCity(s,0,12*s.Width+16,"Odcięty Skład");donor.ProductionPaused=true;donor.MarketStocks[TradeGood.Iron]=40;Connect(s,12,16);var cut=s.Tiles[12*s.Width+14];cut.Road=false;cut.RoadOwner=-1;s.InvalidateLogistics();Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);Assert(c.LastIndustryBatches==0&&donor.LastMarketLines.Single(l=>l.Good==TradeGood.Iron).IndustrialUsed==0,"Processing crossed a missing road");Balanced(s);});
        test("Enemy interdiction separates the industrial input network",()=>{var s=Fixture();var c=s.Cities[0];c.MarketStocks[TradeGood.Iron]=0;var donor=Engine.AddCity(s,0,12*s.Width+16,"Zaplecze");donor.ProductionPaused=true;donor.MarketStocks[TradeGood.Iron]=40;Connect(s,12,16);s.Relation(0,1).War=true;Engine.AddUnit(s,1,12*s.Width+14,UnitKind.Spearmen);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);Assert(c.LastIndustryBatches==0&&donor.LastMarketLines.Single(l=>l.Good==TradeGood.Iron).IndustrialUsed==0,"Inputs crossed hostile interdiction");Balanced(s);Valid(s);});
        test("A foreign stockpile cannot feed workshops without a delivered import",()=>{var s=Fixture();var c=s.Cities[0];c.MarketStocks[TradeGood.Iron]=0;s.Cities[1].MarketStocks[TradeGood.Iron]=40;Trade(s);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);Assert(c.LastIndustryBatches==0&&c.MarketStocks[TradeGood.Tools]==0,"Treaty gave free foreign inputs");});
        test("Paused workshops retain their ingredients apart from normal household consumption",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);c.ProductionPaused=true;Step(s);Assert(c.LastIndustryBatches==0&&c.LastIndustryWork==0&&c.LastMarketLines.All(l=>l.IndustrialUsed==0),"Paused processing consumed materials");Balanced(s);});
        test("A full siege suspends processing even with labor and ingredients",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);s.Relation(0,1).War=true;foreach(var t in World.Neighbors(s,c.Tile).Take(3))Engine.AddUnit(s,1,t.Id,UnitKind.Spearmen);Step(s);Assert(c.LastIndustryBatches==0&&c.LastIndustryWork==0,"Besieged workshop produced goods");Balanced(s);});
        test("A newly built guildhall cannot claim bonuses from zero historical demand",()=>{var s=Fixture();var c=s.Cities[0];Markets.Tick(s);c.Buildings.Add(Manufacturing.Guildhall);Assert(Manufacturing.ProductionBonus(c)==0&&Manufacturing.CultureBonus(c)==0&&Manufacturing.ProsperityBonus(c)==0,"Zero-demand coverage granted free bonuses");Valid(s);});
        test("Actual product consumption grants the guildhall's production culture and prosperity benefits",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(Manufacturing.Guildhall);c.MarketStocks[TradeGood.Tools]=c.MarketStocks[TradeGood.Textiles]=10;var copy=SaveGame.Deserialize(SaveGame.Serialize(s));copy.Cities[0].MarketStocks[TradeGood.Tools]=copy.Cities[0].MarketStocks[TradeGood.Textiles]=0;Step(s);Step(copy);Assert(Manufacturing.ProductionBonus(c)==.15&&Manufacturing.CultureBonus(c)==3&&Manufacturing.ProsperityBonus(c)==3&&Engine.CityYields(s,c).Production>Engine.CityYields(copy,copy.Cities[0]).Production&&Engine.CityYields(s,c).Culture>Engine.CityYields(copy,copy.Cities[0]).Culture,"Demand did not affect the real economy");Balanced(s);Valid(s);});
        test("Newly manufactured tools reach guild consumption only in the following market phase",()=>{var s=Fixture();var c=s.Cities[0];c.Buildings.Add(Manufacturing.Guildhall);Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);Assert(c.MarketStocks[TradeGood.Tools]>0&&Manufacturing.ProductionBonus(c)==0,"Same-turn output was consumed early");Step(s);Assert(Manufacturing.ProductionBonus(c)>0,"Next-turn guild consumption failed");Balanced(s);Valid(s);});
        test("Processed export prices reflect both markets while raw commodity pricing stays unchanged",()=>{var s=Fixture();Trade(s);var a=s.Cities[0];var b=s.Cities[1];a.MarketStocks[TradeGood.Tools]=6;a.MarketStocks[TradeGood.Salt]=20;b.Buildings.Add(Manufacturing.Guildhall);Assert(Engine.SignTradeContract(s,b.Id,a.Id,TradeGood.Tools,2).Success&&Engine.SignTradeContract(s,b.Id,a.Id,TradeGood.Salt,2).Success,"Trade setup failed");string before=SaveGame.Serialize(s);var plan=Markets.Plan(s);double seller=plan.Cities[a.Id].Single(l=>l.Good==TradeGood.Tools).Price;Assert(plan.Trades[0].Price>Math.Round(seller*1.15,2)&&plan.Trades[1].Price==Math.Round(plan.Cities[a.Id].Single(l=>l.Good==TradeGood.Salt).Price*1.15,2)&&SaveGame.Serialize(s)==before,"Trade pricing or read-only behavior wrong");});
        test("Products are dispatched after production and arrive by an actual paid caravan",()=>{var s=Fixture();Trade(s);var a=s.Cities[0];var b=s.Cities[1];b.Buildings.Add(Manufacturing.Guildhall);Manufacturing.SetPolicy(s,a.Id,CraftRecipe.Tools,50);Assert(Engine.SignTradeContract(s,b.Id,a.Id,TradeGood.Tools,2).Success,"Product contract failed");Step(s);Assert(s.Caravans.Count==0&&a.MarketStocks[TradeGood.Tools]>0,"Products shipped before they existed");Step(s);Assert(s.Caravans.Count==1&&s.TradeContracts[0].LastDelivered>0&&b.LastMarketLines.Single(l=>l.Good==TradeGood.Tools).ForeignIn==0,"Shipment arrived instantly");int id=s.Caravans[0].Id;for(int i=0;i<6&&Caravans.Active(s.Caravans.Single(x=>x.Id==id));i++)Step(s);Assert(s.Caravans.Single(x=>x.Id==id).Status==CaravanStatus.Delivered&&b.LastMarketLines.Single(l=>l.Good==TradeGood.Tools).ForeignIn>0,"Produced exports failed actual delivery");Balanced(s);Valid(s);});
        test("Imported iron feeds production only after its caravan arrives",()=>{var s=Fixture();Trade(s);var c=s.Cities[0];c.MarketStocks[TradeGood.Iron]=0;s.Cities[1].MarketStocks[TradeGood.Iron]=40;Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Assert(Engine.SignTradeContract(s,c.Id,s.Cities[1].Id,TradeGood.Iron,6).Success,"Input contract failed");Step(s);Assert(c.LastIndustryBatches==0,"Dispatched input used before arrival");int id=s.Caravans[0].Id;for(int i=0;i<6&&Caravans.Active(s.Caravans.Single(x=>x.Id==id));i++)Step(s);Assert(s.Caravans.Single(x=>x.Id==id).Status==CaravanStatus.Delivered&&c.LastIndustryBatches>0,"Delivered inputs did not enter the chain");Balanced(s);Valid(s);});
        test("Embargo still stops and destroys an already paid processed-goods caravan",()=>{var s=Fixture();Trade(s);var a=s.Cities[0];var b=s.Cities[1];b.MarketStocks[TradeGood.Tools]=10;Assert(Engine.SignTradeContract(s,a.Id,b.Id,TradeGood.Tools,2).Success,"Tools import failed");Step(s);double gold=s.Player.Gold;s.Player.TradePolicy=TradePolicy.Embargo;int id=s.Caravans[0].Id;for(int i=0;i<3;i++)Step(s);Assert(s.Caravans.Single(x=>x.Id==id).Status==CaravanStatus.Lost&&a.MarketStocks[TradeGood.Tools]==0&&s.TradeContracts[0].LastDelivered==0,"Embargo delivered or refunded goods");Balanced(s);Valid(s);});
        test("Capture retains physical workshops and goods but resets plans and accounting context",()=>{var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);double goods=c.MarketStocks[TradeGood.Tools];ProvincialPolitics.Transfer(s,c,1);Assert(c.Buildings.Contains(Manufacturing.Toolmakers)&&c.MarketStocks[TradeGood.Tools]==goods&&c.IndustryShare==0&&c.LastIndustryPolicyTurn==-1&&c.LastIndustryTurn==0&&c.LastIndustryInputs.Count==0,"Capture lost goods or inherited production orders");Valid(s);});
        test("AI builds and funds a real input-backed workshop through ordinary turns",()=>{var s=Fixture();var c=s.Cities[1];var f=s.Factions[1];f.Technologies.UnionWith(EpochCatalog.All.Take(5).SelectMany(e=>e.Technologies));for(int i=0;i<5;i++)f.EpochChoices[i]=0;c.MarketStocks[TradeGood.Iron]=40;foreach(var p in Engine.AvailableProjects(s,c).Where(p=>p.Unit==null&&!Manufacturing.Project(p.Id)&&!ProductionPlanning.Repeatable(p)).ToArray())c.Buildings.Add(p.Id);c.Buildings.UnionWith(["workshop","factory"]);for(int i=0;i<4;i++)Engine.AddUnit(s,1,c.Tile,UnitKind.Spearmen);Step(s);Assert(c.Project==Manufacturing.Toolmakers,"AI did not select stocked processing");c.ProductionPaused=false;c.Production=159.9;Step(s);Assert(c.Buildings.Contains(Manufacturing.Toolmakers)&&c.IndustryShare>0,"AI failed construction or policy");Step(s);Assert(c.MarketStocks[TradeGood.Tools]>0&&c.LastIndustryWork>0,"AI created no real output");Balanced(s);Valid(s);});
        test("Current manufacturing saves preserve deterministic economic and shipment continuation",()=>{var s=Fixture();Trade(s);var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Engine.SignTradeContract(s,s.Cities[1].Id,c.Id,TradeGood.Tools,2);Step(s);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(copy.Version==SaveGame.CurrentVersion&&copy.Cities[0].LastIndustryBatches==c.LastIndustryBatches,"Manufacturing receipt lost");for(int i=0;i<4;i++){Step(s);Step(copy);Assert(SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Manufacturing future diverged");}});
        test("V23 migration retains military reserves and old ledgers without inventing processed goods",()=>{var s=StageTwentyFiveSpecs.Fixture();var c=s.Cities[0];c.Buildings.Add(FieldLogistics.Depot);c.MilitarySupplies=18;var u=Engine.AddUnit(s,0,c.Tile,UnitKind.Spearmen);u.SupplyReserve=2;Markets.Tick(s);var node=JsonNode.Parse(SaveGame.Serialize(s))!;node["Version"]=23;foreach(var city in node["Cities"]!.AsArray()){var obj=city!.AsObject();foreach(var key in obj.Select(p=>p.Key).Where(k=>k.Contains("Industry")).ToArray())obj.Remove(key);obj["MarketStocks"]!.AsObject().Remove("Tools");obj["MarketStocks"]!.AsObject().Remove("Textiles");var lines=obj["LastMarketLines"]!.AsArray();for(int i=lines.Count-1;i>=0;i--){string good=lines[i]!["Good"]!.GetValue<string>();if(good is "Tools" or "Textiles")lines.RemoveAt(i);else lines[i]!.AsObject().Remove("IndustrialUsed");}}string old=node.ToJsonString();var loaded=SaveGame.Deserialize(old);Assert(loaded.Version==SaveGame.CurrentVersion&&loaded.Cities[0].MilitarySupplies==18&&loaded.Units.Single().SupplyReserve==2&&loaded.Cities.All(x=>x.MarketStocks[TradeGood.Tools]==0&&x.MarketStocks[TradeGood.Textiles]==0&&x.IndustryShare==0)&&loaded.Cities[0].LastMarketLines.Count==5,"Migration invented goods or lost previous systems");string dir=Path.Combine(Path.GetTempPath(),"crown-craft-"+Guid.NewGuid());Directory.CreateDirectory(dir);string path=Path.Combine(dir,"campaign.crown");try{File.WriteAllText(path,old);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v23.bak")==old&&SaveGame.Read(path).Version==SaveGame.CurrentVersion,"Exact V23 backup missing");}finally{foreach(string file in new[]{path,path+".tmp",path+".v23.bak"})File.Delete(file);Directory.Delete(dir);}});
        test("Validation rejects forged recipes work dates input sources and inconsistent industrial ledgers",()=>{for(int mode=0;mode<11;mode++){var s=Fixture();var c=s.Cities[0];Manufacturing.SetPolicy(s,c.Id,CraftRecipe.Tools,50);Step(s);switch(mode){case 0:c.IndustryShare=100;break;case 1:c.LastIndustryPolicyTurn=s.Turn+1;break;case 2:c.IndustryRecipe=(CraftRecipe)999;break;case 3:c.LastIndustryWork++;break;case 4:c.LastIndustryInputs[0]=c.LastIndustryInputs[0] with {Quantity=99};break;case 5:c.LastIndustryBatches=99;break;case 6:c.LastIndustryInputs[0]=c.LastIndustryInputs[0] with {Good=TradeGood.Salt};break;case 7:c.LastMarketLines[0]=c.LastMarketLines[0] with {IndustrialUsed=-1};break;case 8:c.LastIndustryTurn=s.Turn;break;case 9:c.LastIndustryInputs[0]=c.LastIndustryInputs[0] with {CityId=9999};break;case 10:c.Buildings.Remove(Manufacturing.Toolmakers);break;}bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Forged industrial state accepted");}});
        test("Older formats cannot smuggle new facilities products or product contracts",()=>{for(int mode=0;mode<3;mode++){var s=Fixture();if(mode==1){s.Cities[0].Buildings.Remove(Manufacturing.Toolmakers);s.Cities[0].MarketStocks[TradeGood.Tools]=1;}if(mode==2){s.Cities[0].Buildings.Remove(Manufacturing.Toolmakers);Trade(s);Engine.SignTradeContract(s,s.Cities[1].Id,s.Cities[0].Id,TradeGood.Tools,2);}s.Version=23;bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Old format accepted new economy");}});
    }
}
